update shebao_payment_plan_detail
set distribution_result = 'failed',
    fail_reason = #{reason}
where plan_id = #{planId}
  and del_flag = '0'
  and id_card_no = #{idCardNo}

mapper.select:
select d.id as id, d.plan_id as planId, p.batch_no as batchNo, date_format(d.business_period, '%Y-%m') as businessPeriod, d.subsidy_type as subsidyType, d.person_name as personName, d.id_card_no as idCardNo, d.distribution_amount as distributionAmount, d.bank_account as bankAccount, d.account_name as accountName, d.grant_org as grantOrg, d.fail_reason as failReason, d.village_name as villageName, d.street_name as streetName, d.payment_month as paymentMonth from shebao_payment_plan_detail d inner join shebao_payment_plan p on p.id = d.plan_id and p.del_flag = '0' where d.del_flag = '0' and d.distribution_result = 'failed' and p.finance_status = 'finance_approved'
and p.batch_no = #{req.batchNo}
and d.person_name like concat('%', #{req.personName}, '%')
and d.subsidy_type = #{req.subsidyType}
and d.business_period = #{req.businessPeriodDate}
and d.fail_reason like concat('%', #{req.failReason}, '%')
order by p.batch_no desc, d.id asc
